	@ConfigItem(keyName = "divineSuperCombat", name = "Divine super combat",
		description = "Remind before divine super combat expires", section = MENAPHITE, position = 12)
	default boolean divineSuperCombat() { return true; }

	@ConfigItem(keyName = "divineSuperAttack", name = "Divine super attack",
		description = "Remind before divine super attack expires", section = MENAPHITE, position = 13)
	default boolean divineSuperAttack() { return true; }

	@ConfigItem(keyName = "divineSuperStrength", name = "Divine super strength",
		description = "Remind before divine super strength expires", section = MENAPHITE, position = 14)
	default boolean divineSuperStrength() { return true; }

	@ConfigItem(keyName = "divineSuperDefence", name = "Divine super defence",
		description = "Remind before divine super defence expires", section = MENAPHITE, position = 15)
	default boolean divineSuperDefence() { return true; }

	@ConfigItem(keyName = "divineRanging", name = "Divine ranging",
		description = "Remind before divine ranging expires", section = MENAPHITE, position = 16)
	default boolean divineRanging() { return true; }

	@ConfigItem(keyName = "divineBastion", name = "Divine bastion",
		description = "Remind before divine bastion expires", section = MENAPHITE, position = 17)
	default boolean divineBastion() { return true; }

	@ConfigItem(keyName = "divineBattlemage", name = "Divine battlemage",
		description = "Remind before divine battlemage expires", section = MENAPHITE, position = 18)
	default boolean divineBattlemage() { return true; }

	@ConfigSection(name = "Misc", description = "Additional reminder conditions", position = 2)
	String MISC = "misc";

	@ConfigItem(keyName = "heartOnlyWhenBanked", name = "Remind for heart only when banked",
		description = "Only display Menaphite reminders for the saturated heart when the boost is close to expiring but the heart is no longer in the inventory (e.g. wilderness use cases)",
		section = MISC, position = 0)
	default boolean heartOnlyWhenBanked() { return true; }

	@ConfigItem(keyName = "promptPreserve", name = "Time Preserve for Menaphite",
		description = "If Menaphite reminders are enabled and a remedy is in your inventory, predicts an optimal time to activate Preserve",
		section = PRESERVE, position = 10)
	default boolean promptPreserve() { return true; }
	@ConfigItem(keyName = "preserveNotification", name = "Send notification", description = "Send a RuneLite Preserve notification", section = PRESERVE, position = 1)
	default boolean preserveNotification() { return false; }

	@ConfigItem(keyName = "preserveInfobox", name = "Show infobox", description = "Show a Preserve activation infobox", section = PRESERVE, position = 2)
	default boolean preserveInfobox() { return true; }

	@ConfigItem(keyName = "preserveOverhead", name = "Send overhead", description = "Show the Preserve message above your head", section = PRESERVE, position = 3)
	default boolean preserveOverhead() { return true; }

	@ConfigItem(keyName = "preserveMessage", name = "Overhead message", description = "Text for the Preserve overhead reminder", section = PRESERVE, position = 4)
	default String preserveMessage() { return "Enable Preserve!"; }

	@ConfigItem(keyName = "preserveColour", name = "Overhead colour", description = "Colour of the Preserve overhead reminder", section = PRESERVE, position = 5)
	default Color preserveColour() { return new Color(180, 100, 255); }

	@Range(min = 0, max = 100)
	@ConfigItem(keyName = "minimumPreserveBoost", name = "Minimum boost for Preserve-on",
		description = "Minimum levels above base in any enabled skill for ordinary Preserve-on reminders. Default: 10. 0 means no minimum. Does not affect Preserve-off or planned Menaphite/salts timing.",
		section = PRESERVE, position = 6)
	default int minimumPreserveBoost() { return 10; }

	@ConfigItem(keyName = "preserveCombat", name = "Preserve combat boosts", description = "Prompt for regularly-decaying Attack, Strength, Ranged and Magic boosts", section = PRESERVE, position = 7)
	default boolean preserveCombat() { return true; }

	@ConfigItem(keyName = "preserveDefence", name = "Preserve defence boosts", description = "Prompt for regularly-decaying Defence boosts, independently of combat boosts. Does not affect Preserve-off warnings or planned Menaphite/salts timing.", section = PRESERVE, position = 8)
	default boolean preserveDefence() { return false; }

	@ConfigItem(keyName = "preserveNonCombat", name = "Preserve skilling boosts", description = "Prompt when a regularly-decaying non-combat boost is detected", section = PRESERVE, position = 9)
	default boolean preserveNonCombat() { return false; }
}

package com.menaphite;

import com.google.inject.Provides;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Preserve & Menaphite Optimiser",
	description = "Optimises Preserve and Menaphite remedy timing to maximise boost duration",
	tags = {"preserve", "menaphite", "remedy", "divine", "potion", "boost", "heart", "saturated", "timer", "reminder", "decay", "stats"}
)
public class MenaphiteRemedyRemindersPlugin extends Plugin
{
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private MenaphiteRemedyRemindersConfig config;
	@Inject private Notifier notifier;
	@Inject private ItemManager itemManager;
	@Inject private InfoBoxManager infoBoxManager;
	@Inject private ReminderOverhead overhead;
	@Inject private OverlayManager overlayManager;
	@Inject private PreserveReminder preserveReminder;

	private final ReminderTimers timers = new ReminderTimers();
	private final Map<Effect, ReminderInfoBox> infoBoxes = new EnumMap<>(Effect.class);
	private volatile boolean running;
	private boolean needsSync;
	private boolean restoreDecayOnSync;
	@Provides
	MenaphiteRemedyRemindersConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(MenaphiteRemedyRemindersConfig.class);
	}

	@Override
	protected void startUp()
	{
		running = true;
		overlayManager.add(overhead);
		needsSync = true;
		restoreDecayOnSync = client.getGameState() != GameState.LOGGED_IN;
		clientThread.invokeLater(() ->
		{
			if (running && client.getGameState() == GameState.LOGGED_IN)
			{
				synchronizeTimers();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		running = false;
		preserveReminder.reset();
		overlayManager.remove(overhead);
		overhead.clear();
		clearInfoBoxes();
		timers.clear();
		needsSync = true;
	}

	private void synchronizeTimers()
	{
		preserveReminder.initialize(restoreDecayOnSync);
		restoreDecayOnSync = false;
		for (Effect effect : Effect.values()) { updateTimer(effect.varbit); }
		updateTimer(VarbitID.STATRENEWAL_POTION_TIMER);
		updateTimer(VarbitID.MOONLIGHT_POTION_TIME);
		needsSync = false;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (!running || client.getGameState() != GameState.LOGGED_IN) { return; }
		int id = event.getVarbitId();
		preserveReminder.onVarbitChanged(id);
		if (Effect.forVarbit(id) != null || id == VarbitID.STATRENEWAL_POTION_TIMER
			|| id == VarbitID.MOONLIGHT_POTION_TIME)
		{
			updateTimer(id);
		}
	}

	private void updateTimer(int id)
	{
		int value = client.getVarbitValue(id);
		// CS2 buff_bar_get_value uses 25 game ticks per stat-renewal timer unit.
		int ticks = id == VarbitID.STATRENEWAL_POTION_TIMER ? value * 25 : value;
		if (timers.updateTimerFromVarbit(id, ticks))
		{
			Effect effect = Effect.forVarbit(id);
			if (effect != null) { removeInfoBox(effect); }
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!running || client.getGameState() != GameState.LOGGED_IN) { return; }
		if (needsSync) { synchronizeTimers(); }
		timers.tick();
		boolean sipWindow = updateReminders(true);
		preserveReminder.tick(this, nextReminderTarget(), sipWindow);
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (running && client.getGameState() == GameState.LOGGED_IN) { preserveReminder.onStatChanged(event); }
	}

	private int nextReminderTarget()
	{
		int target = Integer.MAX_VALUE;
		if (!config.menaphiteEnabled() || !hasRemedy() || !(config.sendNotification() || config.showInfobox() || config.showOverhead())) { return target; }
		int threshold = ReminderTimers.reminderTicks(config.remindSeconds());
		for (Effect effect : Effect.values())
		{
			if (effect.enabled(config) && timers.applicable(effect)
				&& (effect != Effect.SATURATED_HEART || canRemindForHeart()))
			{
				target = Math.min(target, client.getTickCount() + timers.remaining(effect) - threshold);
			}
		}
		return target;
	}

	private boolean hasRemedy()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		return inventory != null && (inventory.contains(ItemID._1DOSESTATRENEWAL)
			|| inventory.contains(ItemID._2DOSESTATRENEWAL)
			|| inventory.contains(ItemID._3DOSESTATRENEWAL)
			|| inventory.contains(ItemID._4DOSESTATRENEWAL));
	}

	private boolean updateReminders(boolean mayNotify)
	{
		if (!config.menaphiteEnabled() || !hasRemedy())
		{
			clearOutputs();
			return false;
		}
		int threshold = ReminderTimers.reminderTicks(config.remindSeconds());
		boolean anyVisibleReminder = false;
		boolean sipWindow = false;
		for (Effect effect : Effect.values())
		{
			boolean applicable = effect.enabled(config) && timers.applicable(effect)
				&& (effect != Effect.SATURATED_HEART || canRemindForHeart());
			sipWindow |= applicable && timers.remaining(effect) <= threshold;
			if (mayNotify && applicable && timers.remind(effect, threshold))
			{
				if (config.sendNotification())
				{
					notifier.notify("Sip Menaphite remedy! " + effect.displayName + " expires in about "
						+ config.remindSeconds() + "s");
				}
				if (config.showOverhead()) { overhead.show(); }
			}
			boolean visible = applicable && timers.reminded(effect) && timers.remaining(effect) <= threshold;
			anyVisibleReminder |= visible;
			if (visible && config.showInfobox())
			{
				ReminderInfoBox box = infoBoxes.get(effect);
				if (box == null)
				{
					box = new ReminderInfoBox(itemManager.getImage(ItemID._4DOSESTATRENEWAL), this, effect);
					infoBoxes.put(effect, box);
					box.update(timers.remaining(effect));
					infoBoxManager.addInfoBox(box);
				}
				box.update(timers.remaining(effect));
			}
			else { removeInfoBox(effect); }
		}
		if (!config.showOverhead() || !anyVisibleReminder) { overhead.clear(); }
		return sipWindow && (config.sendNotification() || config.showInfobox() || config.showOverhead());
	}

	private boolean canRemindForHeart()
	{
		if (!config.heartOnlyWhenBanked()) { return true; }
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		// An unavailable inventory is not evidence that the heart has been banked.
		return inventory != null && !inventory.contains(ItemID.SATURATED_HEART)
			&& !inventory.contains(ItemID.Cert.SATURATED_HEART);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (MenaphiteRemedyRemindersConfig.GROUP.equals(event.getGroup()))
		{
			clientThread.invokeLater(() ->
			{
				if (running && client.getGameState() == GameState.LOGGED_IN)
				{
					boolean sipWindow = updateReminders(false);
					preserveReminder.tick(this, nextReminderTarget(), sipWindow);
				}
			});
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
			case LOGIN_SCREEN_AUTHENTICATOR:
				preserveReminder.logout();
				restoreDecayOnSync = true;
				reset();
				break;
			case HOPPING:
				preserveReminder.logout();
				restoreDecayOnSync = true;
				clearOutputs();
				needsSync = true;
				break;
			case CONNECTION_LOST:
				preserveReminder.reset();
				restoreDecayOnSync = false;
				clearOutputs();
				needsSync = true;
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			reset();
			// Wait for new server timer updates; do not reseed from pre-death values.
			needsSync = false;
		}
	}

	private void removeInfoBox(Effect effect)
	{
		ReminderInfoBox box = infoBoxes.remove(effect);
		if (box != null) { infoBoxManager.removeInfoBox(box); }
	}

	private void clearOutputs()
	{
		clearInfoBoxes();
		overhead.clear();
	}

	private void clearInfoBoxes()
	{
		for (ReminderInfoBox box : infoBoxes.values()) { infoBoxManager.removeInfoBox(box); }
		infoBoxes.clear();
	}

	private void reset()
	{
		preserveReminder.reset();
		clearOutputs();
		timers.clear();
		needsSync = true;
	}
}

package com.menaphite;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.AlphaComposite;
import java.awt.image.BufferedImage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.infobox.InfoBox;

final class PreserveInfoBox extends InfoBox
{
	PreserveInfoBox(BufferedImage image, Plugin plugin, boolean turnOff)
	{
		super(captionedImage(image, turnOff), plugin);
	}

	private static BufferedImage captionedImage(BufferedImage icon, boolean turnOff)
	{
		BufferedImage image = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setComposite(AlphaComposite.SrcOver.derive(0.5f));
			graphics.drawImage(icon, (32 - icon.getWidth()) / 2, (32 - icon.getHeight()) / 2, null);
			graphics.setComposite(AlphaComposite.SrcOver);
			graphics.setFont(FontManager.getRunescapeSmallFont());
			int y = 15;
			for (String line : new String[]{"Turn", turnOff ? "off" : "on"})
			{
				int x = (32 - graphics.getFontMetrics().stringWidth(line)) / 2;
				graphics.setColor(Color.BLACK);
				graphics.drawString(line, x + 1, y + 1);
				graphics.setColor(Color.WHITE);
				graphics.drawString(line, x, y);
				y += 12;
			}
		}
		finally { graphics.dispose(); }
		return image;
	}

	void update(PreservePlan plan, int predictedTicks, boolean turnOff)
	{
		if (turnOff)
		{
			setTooltip("Turn off Preserve: no active boosts benefit from it.");
			return;
		}
		if (plan == null)
		{
			setTooltip("Turn on Preserve to extend your boosted stats.");
			return;
		}
		setTooltip("Turn on Preserve."
			+ "<br>Estimated first decay after the Menaphite reminder: "
			+ (predictedTicks * 6 / 10) + "s if enabled now.");
	}

	// RuneLite's caption renderer is single-line; the image carries both lines.
	@Override public String getText() { return ""; }
	@Override public Color getTextColor() { return Color.RED; }
}

package com.menaphite;

/** Chooses one activation, followed by leaving Preserve on. */
final class PreservePlan
{
	private static final int REACTION_TICKS = 17;
	final int target;
	final int enable;
	final int deadline;
	final int remaining;

	private PreservePlan(int target, int enable, int remaining)
	{
		this.target = target;
		this.enable = enable;
		this.deadline = enable + REACTION_TICKS;
		this.remaining = remaining;
	}

	static PreservePlan align(CombatDecayCycle cycle, int now, int target)
	{
		return align(cycle, now, target, false);
	}

	static PreservePlan align(CombatDecayCycle cycle, int now, int target, boolean regularBoost)
	{
		int delay = target - now;
		if (!cycle.known() || delay < REACTION_TICKS || delay > 500) { return null; }
		int[] outcomes = new int[delay + 1];
		for (int enable = 0; enable <= delay; enable++)
		{
			outcomes[enable] = afterSip(cycle, delay, enable);
		}
		// Regular boosts also benefit from enabling now when sip timing is unchanged.
		int best = afterSip(cycle, delay, Integer.MAX_VALUE) - (regularBoost ? 1 : 0);
		PreservePlan plan = null;
		for (int enable = 0; enable + REACTION_TICKS <= delay; enable++)
		{
			// Score the whole reaction window, not an unrealistically instant click.
			int worst = 150;
			for (int reaction = 0; reaction <= REACTION_TICKS; reaction++)
			{
				worst = Math.min(worst, outcomes[enable + reaction]);
			}
			if (worst > best || (!regularBoost && plan != null && worst == best))
			{
				best = worst;
				plan = new PreservePlan(target, now + enable, best);
			}
		}
		return plan;
	}

	static int afterSip(CombatDecayCycle cycle, int delay, int enable)
	{
		CombatDecayCycle simulation = cycle.copy();
		for (int tick = 1; tick <= delay + 150; tick++)
		{
			// Count a decay on the sip tick conservatively as immediate stat loss.
			if (simulation.step(tick > enable) && tick >= delay) { return tick - delay; }
		}
		return 0;
	}

	boolean matches(CombatDecayCycle cycle, int now, int target)
	{
		if (this.target != target || now > deadline) { return false; }
		for (int activation = Math.max(now, enable); activation <= deadline; activation++)
		{
			if (afterSip(cycle, target - now, activation - now) < remaining) { return false; }
		}
		return true;
	}
}

package com.menaphite;

import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.Prayer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.Notifier;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

final class PreserveReminder
{
	@Inject private Client client;
	@Inject private MenaphiteRemedyRemindersConfig config;
	@Inject private SpriteManager spriteManager;
	@Inject private InfoBoxManager infoBoxManager;
	@Inject private ConfigManager configManager;
	@Inject private Notifier notifier;
	@Inject private ReminderOverhead overhead;
	private static final String SAVED_SEGMENT = "combatDecaySegment";

	private final CombatDecayCycle cycle = new CombatDecayCycle();
	private final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
	private PreservePlan plan;
	private PreserveInfoBox box;
	private boolean boxTurnsOff;
	private int smellingSaltsExpiry = -1;
	private int plannedMenaphiteTarget = -1;
	private boolean tracking;
	private boolean restored;
	private boolean notified;
	private boolean overheadShown;


	void initialize(boolean login)
	{
		if (!tracking)
		{
			Integer segment = configManager.getRSProfileConfiguration(MenaphiteRemedyRemindersConfig.GROUP, SAVED_SEGMENT, int.class);
			configManager.unsetRSProfileConfiguration(MenaphiteRemedyRemindersConfig.GROUP, SAVED_SEGMENT);
			if (login && !cycle.known() && segment != null && !client.isPrayerActive(Prayer.PRESERVE))
			{
				cycle.restore(segment, client.getTickCount());
				restored = cycle.known();
			}
			tracking = true;
		}
		for (Skill skill : new Skill[]{Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.MAGIC})
		{
			levels.put(skill, client.getBoostedSkillLevel(skill));
		}
		syncSmellingSaltsExpiry();
	}

	void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		if (skill != Skill.ATTACK && skill != Skill.STRENGTH && skill != Skill.DEFENCE
			&& skill != Skill.RANGED && skill != Skill.MAGIC) { return; }
		int current = event.getBoostedLevel();
		Integer previous = levels.put(skill, current);
		if (previous != null && previous == current + 1 && current >= event.getLevel()
			&& !reboostingEffectActive() && !divineProtected(skill))
		{
			int now = client.getTickCount();
			cycle.advance(now, client.isPrayerActive(Prayer.PRESERVE));
			cycle.observe(now);
			restored = false;
		}
	}

	private boolean divineProtected(Skill skill)
	{
		boolean melee = skill == Skill.ATTACK || skill == Skill.STRENGTH || skill == Skill.DEFENCE;
		if (melee && client.getVarbitValue(VarbitID.DIVINECOMBAT_POTION_TIME) > 0) { return true; }
		if ((skill == Skill.DEFENCE || skill == Skill.RANGED)
			&& client.getVarbitValue(VarbitID.DIVINEBASTION_POTION_TIME) > 0) { return true; }
		if ((skill == Skill.DEFENCE || skill == Skill.MAGIC)
			&& client.getVarbitValue(VarbitID.DIVINEBATTLEMAGE_POTION_TIME) > 0) { return true; }
		int varbit;
		switch (skill)
		{
			case ATTACK: varbit = VarbitID.DIVINEATTACK_POTION_TIME; break;
			case STRENGTH: varbit = VarbitID.DIVINESTRENGTH_POTION_TIME; break;
			case DEFENCE: varbit = VarbitID.DIVINEDEFENCE_POTION_TIME; break;
			case RANGED: varbit = VarbitID.DIVINERANGE_POTION_TIME; break;
			case MAGIC:
				if (heartProtected()) { return true; }
				varbit = VarbitID.DIVINEMAGIC_POTION_TIME;
				break;
			default: return false;
		}
		return client.getVarbitValue(varbit) > 0;
	}

	private boolean heartProtected()
	{
		// The cooldown is shared with imbued heart, whose boost is never divine.
		if (client.getVarbitValue(VarbitID.SATURATED_HEART_TIME) <= 0) { return false; }
		// Compare game ticks, not raw varbits: heart units are 10 ticks, renewal units 25.
		int heartTicks = client.getVarbitValue(VarbitID.IMBUED_HEART_TIMER) * 10;
		int renewalTicks = client.getVarbitValue(VarbitID.STATRENEWAL_POTION_TIMER) * 25;
		// Equal durations count as Menaphite being applied after the heart.
		return heartTicks > renewalTicks;
	}

	void onVarbitChanged(int id)
	{
		if (id == VarbitID.TOA_MIDRAIDLOOT_STATS_TIMER) { syncSmellingSaltsExpiry(); }
		if (id == VarbitID.PRAYER_PRESERVE && !client.isPrayerActive(Prayer.PRESERVE))
		{
			cycle.preserveTicks = 0;
		}
	}

	void tick(Plugin plugin, int target)
	{
		tick(plugin, target, false);
	}

	void tick(Plugin plugin, int target, boolean menaphiteSipWindow)
	{
		int now = client.getTickCount();
		boolean active = client.isPrayerActive(Prayer.PRESERVE);
		cycle.advance(now, active);
		boolean regular = hasRegularBoost();
		int menaphiteTarget = config.promptPreserve() ? target : Integer.MAX_VALUE;
		// Keep Preserve through the whole eligible sip window, including reaction time.
		boolean turnOff = active && !hasNonDivineBoost() && !menaphiteSipWindow
			&& !awaitingPlannedMenaphite(now, menaphiteTarget);
		int saltsTarget = smellingSaltsEffectActive() && !hasSmellingSalts() ? smellingSaltsExpiry : Integer.MAX_VALUE;
		int syncTarget = Math.min(menaphiteTarget, saltsTarget);
		boolean preempt = syncTarget != Integer.MAX_VALUE && syncTarget > now;
		if (!config.preserveEnabled() || (!regular && !preempt && !turnOff) || overloadEffectActive()
			|| (smellingSaltsEffectActive() && hasSmellingSalts())
			|| (!active && hasCarriedReboostingPotion())
			|| client.getVarbitValue(VarbitID.PRAYER_PRESERVE_UNLOCKED) == 0
			|| client.getRealSkillLevel(Skill.PRAYER) < 55 || client.getBoostedSkillLevel(Skill.PRAYER) <= 0)
		{
			cancel();
			return;
		}
		if (turnOff)
		{
			plan = null;
			showPrompt(plugin, now, true);
			return;
		}
		if (active)
		{
			cancel();
			return;
		}
		if (preempt)
		{
			// A regular boost permits early activation, but never bypass the sip timing.
			if (!cycle.known() || (!regular && (long) syncTarget - now > 150))
			{
				cancel();
				return;
			}
			if (plan != null && !plan.matches(cycle, now, syncTarget)) { plan = null; }
			if (plan == null) { plan = PreservePlan.align(cycle, now, syncTarget, regular); }
			if (plan == null || now < plan.enable)
			{
				clearOutputs();
				return;
			}
		}
		else
		{
			plan = null;
			if (!hasRegularBoost(Math.max(1, config.minimumPreserveBoost())))
			{
				clearOutputs();
				return;
			}
		}
		if (plan != null && plan.target == menaphiteTarget) { plannedMenaphiteTarget = plan.target; }
		showPrompt(plugin, now, false);
	}

	private boolean awaitingPlannedMenaphite(int now, int menaphiteTarget)
	{
		return plannedMenaphiteTarget == menaphiteTarget && menaphiteTarget > now;
	}

	private void showPrompt(Plugin plugin, int now, boolean turnOff)
	{
		if (config.preserveNotification() && !notified)
		{
			notifier.notify(turnOff ? "Turn off Preserve: no active boosts benefit from it."
				: "Enable Preserve and leave it on to extend your boosted stats.");
			notified = true;
		}
		if (config.preserveOverhead() && !overheadShown)
		{
			if (turnOff) { overhead.showPreserveOff(); }
			else { overhead.showPreserve(); }
			overheadShown = true;
		}
		if (!config.preserveOverhead()) { overhead.clearPreserve(); overheadShown = false; }
		if (!config.preserveInfobox()) { removeBox(); return; }
		boolean added = false;
		if (box != null && boxTurnsOff != turnOff) { removeBox(); }
		if (box == null)
		{
			BufferedImage image = spriteManager.getSprite(SpriteID.Prayeron.PRESERVE, 0);
			if (image == null) { return; }
			box = new PreserveInfoBox(image, plugin, turnOff);
			boxTurnsOff = turnOff;
			added = true;
		}
		box.update(plan, plan == null ? 0 : PreservePlan.afterSip(cycle, plan.target - now, 0), turnOff);
		if (restored) { box.setTooltip(box.getTooltip() + "<br>Cycle estimated from the saved logout segment."); }
		if (added) { infoBoxManager.addInfoBox(box); }
	}

	void cancel()
	{
		plan = null;
		clearOutputs();
	}

	private void clearOutputs()
	{
		notified = false;
		overheadShown = false;
		overhead.clearPreserve();
		removeBox();
	}

	private boolean hasRegularBoost()
	{
		return hasRegularBoost(1);
	}

	private boolean hasRegularBoost(int minimum)
	{
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL || skill == Skill.HITPOINTS || skill == Skill.PRAYER) { continue; }
			boolean combat = skill == Skill.ATTACK || skill == Skill.STRENGTH || skill == Skill.DEFENCE
				|| skill == Skill.RANGED || skill == Skill.MAGIC;
			boolean enabled = skill == Skill.DEFENCE ? config.preserveDefence()
				: combat ? config.preserveCombat() : config.preserveNonCombat();
			if (enabled
				&& client.getBoostedSkillLevel(skill) - client.getRealSkillLevel(skill) >= minimum
				&& (!combat || !divineProtected(skill))) { return true; }
		}
		return false;
	}

	private boolean hasNonDivineBoost()
	{
		for (Skill skill : Skill.values())
		{
			if (skill == Skill.OVERALL || skill == Skill.HITPOINTS || skill == Skill.PRAYER) { continue; }
			if (client.getBoostedSkillLevel(skill) > client.getRealSkillLevel(skill) && !divineProtected(skill))
			{
				return true;
			}
		}
		return false;
	}

	private boolean reboostingEffectActive()
	{
		return overloadEffectActive() || smellingSaltsEffectActive();
	}

	private boolean overloadEffectActive()
	{
		return client.getVarbitValue(VarbitID.NZONE_OVERLOAD_POTION_EFFECTS) > 0
			|| client.getVarbitValue(VarbitID.RAIDS_OVERLOAD_TIMER) > 0
			|| client.getVarbitValue(VarbitID.DEADMAN_OVERLOAD_POTION_EFFECTS) > 0;
	}

	private boolean smellingSaltsEffectActive()
	{
		return client.getVarbitValue(VarbitID.TOA_MIDRAIDLOOT_STATS_TIMER) > 0;
	}

	private void syncSmellingSaltsExpiry()
	{
		int timer = client.getVarbitValue(VarbitID.TOA_MIDRAIDLOOT_STATS_TIMER);
		// The salts buff bar timer advances in 25-tick units.
		smellingSaltsExpiry = timer > 0 ? client.getTickCount() + timer * 25 : -1;
	}

	private boolean hasCarriedReboostingPotion()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		return inventory != null && containsAny(inventory,
			ItemID.NZONE1DOSEOVERLOADPOTION, ItemID.NZONE2DOSEOVERLOADPOTION,
			ItemID.NZONE3DOSEOVERLOADPOTION, ItemID.NZONE4DOSEOVERLOADPOTION,
			ItemID.RAIDS_VIAL_OVERLOAD_WEAK_1, ItemID.RAIDS_VIAL_OVERLOAD_WEAK_2,
			ItemID.RAIDS_VIAL_OVERLOAD_WEAK_3, ItemID.RAIDS_VIAL_OVERLOAD_WEAK_4,
			ItemID.RAIDS_VIAL_OVERLOAD_1, ItemID.RAIDS_VIAL_OVERLOAD_2,
			ItemID.RAIDS_VIAL_OVERLOAD_3, ItemID.RAIDS_VIAL_OVERLOAD_4,
			ItemID.RAIDS_VIAL_OVERLOAD_STRONG_1, ItemID.RAIDS_VIAL_OVERLOAD_STRONG_2,
			ItemID.RAIDS_VIAL_OVERLOAD_STRONG_3, ItemID.RAIDS_VIAL_OVERLOAD_STRONG_4,
			ItemID.DEADMAN1DOSEOVERLOAD, ItemID.DEADMAN2DOSEOVERLOAD,
			ItemID.DEADMAN3DOSEOVERLOAD, ItemID.DEADMAN4DOSEOVERLOAD)
			|| hasSmellingSalts();
	}

	private boolean hasSmellingSalts()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		return inventory != null && containsAny(inventory, ItemID.TOA_SUPPLY_STATS_1, ItemID.TOA_SUPPLY_STATS_2);
	}

	private boolean containsAny(ItemContainer inventory, int... itemIds)
	{
		for (int itemId : itemIds)
		{
			if (inventory.contains(itemId)) { return true; }
		}
		return false;
	}

	private void removeBox()
	{
		if (box != null) { infoBoxManager.removeInfoBox(box); box = null; boxTurnsOff = false; }
	}

	void reset()
	{
		if (tracking) { configManager.unsetRSProfileConfiguration(MenaphiteRemedyRemindersConfig.GROUP, SAVED_SEGMENT); }
		cancel();
		cycle.reset();
		levels.clear();
		smellingSaltsExpiry = -1;
		plannedMenaphiteTarget = -1;
		tracking = false;
		restored = false;
	}

	void logout()
	{
		if (!tracking) { return; }
		int segment = client.isPrayerActive(Prayer.PRESERVE) ? -1 : cycle.logoutSegment();
		reset();
		if (segment >= 0)
		{
			// Normal cycles restart their current 12-second segment on login.
			// Preserve-affected cycles are deliberately not extrapolated across logout.
			configManager.setRSProfileConfiguration(MenaphiteRemedyRemindersConfig.GROUP, SAVED_SEGMENT, segment);
		}
	}
}

