package com.menaphite;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.awt.Font;
import net.runelite.client.ui.FontManager;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

@Singleton
final class ReminderOverhead extends Overlay
{
	private final Client client;
	private final MenaphiteRemedyRemindersConfig config;
	private volatile long visibleUntil;
	private volatile long preserveUntil;
	private volatile String preserveText;

	@Inject
	ReminderOverhead(Client client, MenaphiteRemedyRemindersConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	void show() { visibleUntil = System.nanoTime() + TimeUnit.SECONDS.toNanos(5); }
	void clear() { visibleUntil = 0; }
	void showPreserve() { showPreserve(config.preserveMessage()); }
	void showPreserveOff() { showPreserve("Turn off Preserve!"); }
	private void showPreserve(String text)
	{
		preserveText = text;
		preserveUntil = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
	}
	void clearPreserve() { preserveUntil = 0; preserveText = null; }

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}
		Player player = client.getLocalPlayer();
		if (player == null) { return null; }
		boolean menaphite = System.nanoTime() < visibleUntil && config.menaphiteEnabled() && config.showOverhead();
		boolean preserve = System.nanoTime() < preserveUntil && config.preserveEnabled() && config.preserveOverhead();
		if (!menaphite && !preserve) { return null; }
		Font originalFont = graphics.getFont();
		graphics.setFont(FontManager.getRunescapeBoldFont());
		try
		{
			if (menaphite) { draw(graphics, player, config.overheadMessage(), config.overheadColour(), 40); }
			if (preserve)
			{
				draw(graphics, player, preserveText, config.preserveColour(), menaphite ? 65 : 40);
			}
		}
		finally { graphics.setFont(originalFont); }
		return null;
	}

	private void draw(Graphics2D graphics, Player player, String text, Color colour, int height)
	{
		String message = text.trim();
		if (!message.isEmpty())
		{
			Point position = player.getCanvasTextLocation(graphics, message, player.getLogicalHeight() + height);
			if (position != null)
			{
				OverlayUtil.renderTextLocation(graphics, position, message, colour);
			}
		}
	}
}

package com.menaphite;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.VarbitID;

final class ReminderTimers
{
	private final Map<Integer, Snapshot> snapshots = new HashMap<>();
	private long tick;

	private static final class Snapshot
	{
		private int duration;
		private long receivedTick;
		private boolean reminded;

		private int remaining(long now)
		{
			return (int) Math.max(0, duration - Math.max(0, now - receivedTick));
		}
	}

	boolean updateTimerFromVarbit(int varbit, int ticks)
	{
		Snapshot snapshot = snapshots.computeIfAbsent(varbit, ignored -> new Snapshot());
		int duration = Math.max(0, ticks);
		boolean reset = duration == 0 || duration > snapshot.remaining(tick);
		if (reset) { snapshot.reminded = false; }
		snapshot.duration = duration;
		// Varbit events precede GameTick; this sample belongs to the upcoming tick.
		snapshot.receivedTick = tick + 1;
		return reset;
	}

	void tick() { tick++; }

	int remaining(int varbit)
	{
		Snapshot snapshot = snapshots.get(varbit);
		return snapshot == null ? 0 : snapshot.remaining(tick);
	}

	int remaining(Effect effect) { return remaining(effect.varbit); }

	boolean reminded(Effect effect)
	{
		Snapshot snapshot = snapshots.get(effect.varbit);
		return snapshot != null && snapshot.reminded;
	}

	boolean remind(Effect effect, int threshold)
	{
		int left = remaining(effect);
		if (left == 0 || left > threshold || reminded(effect)) { return false; }
		snapshots.get(effect.varbit).reminded = true;
		return true;
	}

	boolean applicable(Effect effect)
	{
		int left = remaining(effect);
		int covered = remaining(VarbitID.STATRENEWAL_POTION_TIMER);
		for (Effect combination : Effect.values())
		{
			if (combination.covers(effect)) { covered = Math.max(covered, remaining(combination)); }
		}
		if (effect == Effect.DIVINE_SUPER_DEFENCE)
		{
			int moonlight = remaining(VarbitID.MOONLIGHT_POTION_TIME);
			if (moonlight > 0) { covered = Math.max(covered, moonlight + 1); }
		}
		return left > covered;
	}

	void clear()
	{
		snapshots.clear();
		tick = 0;
	}

	static int reminderTicks(int seconds) { return (int) Math.ceil(Math.max(1, Math.min(300, seconds)) / 0.6); }
	static int secondsRemaining(int ticks) { return (int) Math.ceil(ticks * 0.6); }
}

